/****** Object:  UserDefinedFunction [dbo].[fn_has_changes]    Script Date: 16/07/2026 16:56:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- ============================================================
-- Helper: kiem tra thay doi thuc su cho UPDATE
-- ============================================================
CREATE   FUNCTION [dbo].[fn_has_changes](@old NVARCHAR(MAX), @new NVARCHAR(MAX))
RETURNS BIT
AS
BEGIN
    RETURN CASE WHEN @old <> @new THEN 1 ELSE 0 END
END;
