/****** Object:  StoredProcedure [dbo].[sp_AutoCancelPendingOrders]    Script Date: 16/07/2026 16:56:51 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Bước 1: Tạo stored procedure xử lý cancel
CREATE   PROCEDURE [dbo].[sp_AutoCancelPendingOrders]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @cutoffTime DATETIME = DATEADD(MINUTE, -30, GETDATE());

    UPDATE [order]
    SET status = 'CANCELLED'
    WHERE status = 'PENDING'
      AND created_at <= @cutoffTime;

    PRINT N'Đã hủy các đơn hàng PENDING quá 30 phút (trước ' + CONVERT(VARCHAR, @cutoffTime, 120) + N').';
END
GO
